def sort_array(array):
    if not array:
        return []

    sum_first_last = array[0] + array[-1]
    is_odd = sum_first_last % 2 != 0

    if is_odd:
        sorted_array = sorted(array)
    else:
        sorted_array = sorted(array, reverse=True)

    sorted_dict = {index: value for index, value in enumerate(sorted_array)}
    result = [sorted_dict.get(index, None) for index in range(len(array))]

    return result

